    trainingDrills: {
      shadowPractice: { description: "Solo rehearsal methodology: Stand in natural stance, sync breath, execute techniques with imaginary threat visualization. Maintain continuous kinetic flow using performance-focused body mechanics, no tension spikes, mirror posture checks. 5-10 min sessions, focus on relaxation, distance management, and combination chaining under movement. Apply flowing entries to shadow flow with emphasis on performance adaptability." },
      partnerDrills: { description: "Controlled interaction protocols: Push/pull sensitivity using performance-focused body mechanics, grab/release flow, strike defense chains, ground transitions. Light intensity, breath sync mandatory, immediate reset on error. 3 min rounds, 30 sec rest, focus on timing, range control, and adaptive response. Apply warrior respect to partner interaction with emphasis on performance adaptability." },
      padWork: { description: "Holding positions: Soft target placement, strike sequence calling, resistance progression. Holder feeds angles, receiver breathes out on strike, holder provides tactile feedback. 2 min rounds, switch every round, focus on penetration, accuracy, and continuous movement. Apply angular angles to target work with emphasis on performance adaptability." },
      sparring: { description: "Light/medium contact guidelines. Breath control mandatory, protective gear worn. Continuous engagement, safety tap for submissions/stress. Focus on flow, distance, and technique over knockout. 3 min work / 1 min rest, 5 rounds. Gloves/foot pads optional per federation rules. Apply dynamic intensity to contact with emphasis on performance adaptability." },
      formKata: { description: "Forms (traditional sequences). Fixed sequences integrating strikes, blocks, stances, weapons, and flowing transitions. Purpose: integrate biomechanics, breath control, spatial awareness, and traditional principles application. 10 min continuous practice, focus on precision, rhythm, and mental discipline. Apply warrior philosophy to form execution with emphasis on performance flow and cultural form." },
      performanceDrills: { description: "Performance-focused drills for enhancing artistic expression and technical precision. Focus on developing fluid movements and cultural form through repetitive practice with proper breathing and performance-focused body mechanics." }
    },
